import re
from datetime import datetime

_DIGITS = "0123456789"
_ANGLE_RE = re.compile(r"<([^<>]*)>")
_EXT_RE = re.compile(r"x|ext|#", re.IGNORECASE)
_ZIP_PLUS4_RE = re.compile(r"([0-9]{4,5})-[0-9]{4}")
_TAG_SPLIT_RE = re.compile(r"[;,]")
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_OPT_OUT_VALUES = {"y", "yes", "true", "1"}
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}


def _all_digits(s):
    return all(c in _DIGITS for c in s)


def _normalize_email(raw):
    s = raw or ""
    m = _ANGLE_RE.search(s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "")
            local = local.split("+", 1)[0]
            s = f"{local}@gmail.com"
    return s


def _is_valid_email(e):
    if e.count("@") != 1:
        return False
    local, domain = e.split("@")
    return (
        bool(local)
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    s = raw or ""
    m = _EXT_RE.search(s)
    if m:
        s = s[:m.start()]
    digits = "".join(c for c in s if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(p):
    return len(p) == 10 and p[0] not in "01"


def _normalize_zip(raw):
    s = (raw or "").strip()
    m = _ZIP_PLUS4_RE.fullmatch(s)
    if m:
        s = m.group(1)
    if len(s) == 4 and _all_digits(s):
        s = "0" + s
    if len(s) == 5 and _all_digits(s):
        return s
    return ""


def _normalize_name(raw):
    s = (raw or "").strip()
    if s and (s.isupper() or s.islower()):
        s = s.title()
    return s


def _parse_updated(raw):
    s = (raw or "").strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def _is_opted_out(raw):
    return (raw or "").strip().lower() in _OPT_OUT_VALUES


def _parse_tags(raw):
    return {t.strip().lower() for t in _TAG_SPLIT_RE.split(raw or "") if t.strip()}


def _pick(group, field):
    """Pick the best row's value for `field`: manual first, then most recent
    `updated`, then earliest input row. Returns "" if no row has a value."""
    cands = [r for r in group if r[field]]
    if not cands:
        return ""
    # Stable multi-pass sort, applied from the lowest-priority key up.
    cands.sort(key=lambda r: r["idx"])
    cands.sort(key=lambda r: r["updated"], reverse=True)
    cands.sort(key=lambda r: r["source"] != "manual")
    return cands[0][field]


def dedupe_contacts(rows):
    # Step 1: normalize each row and drop rows with no valid email or phone.
    recs = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row.get("email", ""))
        phone = _normalize_phone(row.get("phone", ""))
        email_ok = _is_valid_email(email)
        phone_ok = _is_valid_phone(phone)
        if not (email_ok or phone_ok):
            continue
        recs.append({
            "idx": idx,
            "first_name": _normalize_name(row.get("first_name")),
            "last_name": _normalize_name(row.get("last_name")),
            "zip": _normalize_zip(row.get("zip")),
            # Store only valid values, so "" means "does not qualify".
            "email": email if email_ok else "",
            "phone": phone if phone_ok else "",
            "source": (row.get("source") or "").strip().lower(),
            "tags": _parse_tags(row.get("tags")),
            "opted_out": _is_opted_out(row.get("opted_out")),
            "updated": _parse_updated(row.get("updated")),
        })

    # Step 2: link rows that share a valid email, or a valid phone plus
    # the same non-empty last name (case-insensitive). Union-find makes
    # the matching transitive.
    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    first_seen = {}
    for pos, rec in enumerate(recs):
        keys = []
        if rec["email"]:
            keys.append(("email", rec["email"]))
        if rec["phone"] and rec["last_name"]:
            keys.append(("phone", rec["phone"], rec["last_name"].lower()))
        for key in keys:
            if key in first_seen:
                union(first_seen[key], pos)
            else:
                first_seen[key] = pos

    # Step 3: group rows. Dict insertion order follows each group's
    # earliest input row, because recs is already in input order.
    groups = {}
    for pos in range(len(recs)):
        groups.setdefault(find(pos), []).append(recs[pos])

    # Step 4: build one output record per person.
    result = []
    for group in groups.values():
        all_tags = set()
        for r in group:
            all_tags |= r["tags"]
        latest = max(r["updated"] for r in group)
        result.append({
            "first_name": _pick(group, "first_name"),
            "last_name": _pick(group, "last_name"),
            "zip": _pick(group, "zip"),
            "email": _pick(group, "email"),
            "phone": _pick(group, "phone"),
            "source": _pick(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })
    return result
```

Notes on the implementation:

- **Opt-outs:** The function returns opted-out people too, marked `opted_out == "Y"`. Filter them out before sending, e.g. `[p for p in dedupe_contacts(rows) if p["opted_out"] == "N"]`. A person is marked opted out if any of their rows has opted out.
- **Assumptions I made where the rules were unclear:**
  - ZIP+4 handling also accepts a 4-digit prefix (`2139-4307`), so an Excel-mangled ZIP+4 still gets its leading zero back.
  - An `updated` value that matches none of the three formats raises `ValueError` rather than being silently ranked as oldest. This stops the run, so you'll know about bad data before sending.
